        ,sum(case when order_a4_a0 = 1 and order_a5 = 1 then 1.0 else 0.0 end)/sum(order_a5) as repurchase_rate_a5
        ,sum(case when order_a6_a0 = 1 and order_a7 = 1 then 1.0 else 0.0 end)/sum(order_a7) as repurchase_rate_a7
        ,0 as repurchase_rate_a14
from    tmp_union_date_${grass_region_without_quote}
group by 1, 2;

